CREATE TABLE butchery_items(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,item_kind ENUM('raw_material','additive','finished_product','co_product') NOT NULL,unit ENUM('kg','piece','litre') NOT NULL DEFAULT 'kg',default_shelf_life_days INT UNSIGNED NULL,status ENUM('active','inactive') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE butchery_receipts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id INT UNSIGNED NOT NULL,source_type ENUM('internal_btr','external_bra') NOT NULL,livestock_transfer_id BIGINT UNSIGNED NULL,supplier_id INT UNSIGNED NULL,receipt_number VARCHAR(100) NOT NULL UNIQUE,source_reference VARCHAR(120) NULL,received_unit ENUM('head','kg') NOT NULL,received_heads INT UNSIGNED NULL,received_weight_kg DECIMAL(14,3) NULL,unit_cost DECIMAL(14,4) NOT NULL DEFAULT 0,status ENUM('draft','sanitary_pending','accepted','rejected','cancelled') DEFAULT 'sanitary_pending',received_at DATETIME NOT NULL,created_by INT UNSIGNED NOT NULL,validated_by INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,UNIQUE KEY uq_br_livestock_transfer(livestock_transfer_id),UNIQUE KEY uq_br_external_source(source_type,source_reference),CONSTRAINT fk_br_site FOREIGN KEY(site_id) REFERENCES sites(id),CONSTRAINT fk_br_transfer FOREIGN KEY(livestock_transfer_id) REFERENCES livestock_transfers(id),CONSTRAINT fk_br_supplier FOREIGN KEY(supplier_id) REFERENCES suppliers(id),CONSTRAINT fk_br_creator FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE butchery_sanitary_controls(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,receipt_id BIGINT UNSIGNED NOT NULL,temperature_c DECIMAL(6,2) NULL,visual_status ENUM('conform','non_conform') NOT NULL,document_status ENUM('conform','non_conform') NOT NULL,decision ENUM('accept','reject') NOT NULL,notes TEXT NULL,controlled_at DATETIME NOT NULL,controlled_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_bsc_receipt(receipt_id),CONSTRAINT fk_bsc_receipt FOREIGN KEY(receipt_id) REFERENCES butchery_receipts(id),CONSTRAINT fk_bsc_user FOREIGN KEY(controlled_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE butchery_live_lots(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id INT UNSIGNED NOT NULL,receipt_id BIGINT UNSIGNED NOT NULL,livestock_batch_id BIGINT UNSIGNED NULL,lot_number VARCHAR(100) NOT NULL UNIQUE,available_heads INT UNSIGNED NOT NULL,status ENUM('available','partially_slaughtered','depleted','quarantine','rejected') DEFAULT 'available',received_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_bll_receipt(receipt_id),CONSTRAINT fk_bll_site FOREIGN KEY(site_id) REFERENCES sites(id),CONSTRAINT fk_bll_receipt FOREIGN KEY(receipt_id) REFERENCES butchery_receipts(id),CONSTRAINT fk_bll_batch FOREIGN KEY(livestock_batch_id) REFERENCES livestock_batches(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE butchery_slaughters(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,live_lot_id BIGINT UNSIGNED NOT NULL,raw_item_id INT UNSIGNED NOT NULL,slaughter_number VARCHAR(100) NOT NULL UNIQUE,input_heads INT UNSIGNED NOT NULL,gross_weight_kg DECIMAL(14,3) NOT NULL,tare_weight_kg DECIMAL(14,3) NOT NULL DEFAULT 0,net_weight_kg DECIMAL(14,3) NOT NULL,status ENUM('submitted','validated','cancelled') DEFAULT 'submitted',slaughtered_at DATETIME NOT NULL,created_by INT UNSIGNED NOT NULL,validated_by INT UNSIGNED NULL,validated_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_bs_live FOREIGN KEY(live_lot_id) REFERENCES butchery_live_lots(id),CONSTRAINT fk_bs_item FOREIGN KEY(raw_item_id) REFERENCES butchery_items(id),CONSTRAINT fk_bs_creator FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE butchery_raw_lots(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id INT UNSIGNED NOT NULL,item_id INT UNSIGNED NOT NULL,receipt_id BIGINT UNSIGNED NULL,slaughter_id BIGINT UNSIGNED NULL,livestock_batch_id BIGINT UNSIGNED NULL,supplier_id INT UNSIGNED NULL,lot_number VARCHAR(100) NOT NULL UNIQUE,production_date DATE NOT NULL,expiry_date DATE NOT NULL,quantity_kg DECIMAL(14,3) NOT NULL,reserved_kg DECIMAL(14,3) NOT NULL DEFAULT 0,unit_cost DECIMAL(14,4) NOT NULL DEFAULT 0,status ENUM('available','reserved','depleted','expired','quarantine','rejected','cancelled') DEFAULT 'available',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,UNIQUE KEY uq_brl_receipt(receipt_id),UNIQUE KEY uq_brl_slaughter(slaughter_id),KEY idx_brl_available(site_id,item_id,status,expiry_date),CONSTRAINT fk_brl_site FOREIGN KEY(site_id) REFERENCES sites(id),CONSTRAINT fk_brl_item FOREIGN KEY(item_id) REFERENCES butchery_items(id),CONSTRAINT fk_brl_receipt FOREIGN KEY(receipt_id) REFERENCES butchery_receipts(id),CONSTRAINT fk_brl_slaughter FOREIGN KEY(slaughter_id) REFERENCES butchery_slaughters(id),CONSTRAINT fk_brl_batch FOREIGN KEY(livestock_batch_id) REFERENCES livestock_batches(id),CONSTRAINT fk_brl_supplier FOREIGN KEY(supplier_id) REFERENCES suppliers(id),CONSTRAINT chk_brl_nonnegative CHECK(quantity_kg>=0 AND reserved_kg>=0 AND reserved_kg<=quantity_kg)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE butchery_raw_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,raw_lot_id BIGINT UNSIGNED NOT NULL,movement_type ENUM('receipt_in','slaughter_in','production_out','direct_sale_out','reserve','release','reversal') NOT NULL,quantity_kg DECIMAL(14,3) NOT NULL,stock_before_kg DECIMAL(14,3) NOT NULL,stock_after_kg DECIMAL(14,3) NOT NULL,reference_type VARCHAR(80) NOT NULL,reference_id BIGINT UNSIGNED NOT NULL,created_by INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_brm_effect(raw_lot_id,movement_type,reference_type,reference_id),CONSTRAINT fk_brm_lot FOREIGN KEY(raw_lot_id) REFERENCES butchery_raw_lots(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE butchery_recipes(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(60) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,status ENUM('active','inactive') DEFAULT 'active',created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE butchery_recipe_versions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,recipe_id INT UNSIGNED NOT NULL,version_number INT UNSIGNED NOT NULL,status ENUM('active','retired') DEFAULT 'active',effective_from DATE NOT NULL,created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_brv_version(recipe_id,version_number),CONSTRAINT fk_brv_recipe FOREIGN KEY(recipe_id) REFERENCES butchery_recipes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE butchery_recipe_components(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,recipe_version_id BIGINT UNSIGNED NOT NULL,item_id INT UNSIGNED NOT NULL,component_type ENUM('raw_material','additive') NOT NULL,percentage DECIMAL(8,3) NOT NULL,UNIQUE KEY uq_brc_item(recipe_version_id,item_id),CONSTRAINT fk_brc_version FOREIGN KEY(recipe_version_id) REFERENCES butchery_recipe_versions(id),CONSTRAINT fk_brc_item FOREIGN KEY(item_id) REFERENCES butchery_items(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE butchery_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id INT UNSIGNED NOT NULL,recipe_version_id BIGINT UNSIGNED NOT NULL,order_number VARCHAR(100) NOT NULL UNIQUE,planned_input_kg DECIMAL(14,3) NOT NULL,actual_input_kg DECIMAL(14,3) NOT NULL DEFAULT 0,output_kg DECIMAL(14,3) NOT NULL DEFAULT 0,co_product_kg DECIMAL(14,3) NOT NULL DEFAULT 0,loss_kg DECIMAL(14,3) NOT NULL DEFAULT 0,yield_percent DECIMAL(9,3) NOT NULL DEFAULT 0,labor_cost DECIMAL(14,4) NOT NULL DEFAULT 0,energy_cost DECIMAL(14,4) NOT NULL DEFAULT 0,allocated_cost DECIMAL(14,4) NOT NULL DEFAULT 0,total_cost DECIMAL(16,4) NOT NULL DEFAULT 0,cost_per_kg DECIMAL(14,4) NOT NULL DEFAULT 0,production_date DATE NOT NULL,status ENUM('draft','in_progress','results_submitted','validated','cancelled') DEFAULT 'in_progress',created_by INT UNSIGNED NOT NULL,validated_by INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,validated_at DATETIME NULL,deleted_at TIMESTAMP NULL,CONSTRAINT fk_bo_site FOREIGN KEY(site_id) REFERENCES sites(id),CONSTRAINT fk_bo_recipe FOREIGN KEY(recipe_version_id) REFERENCES butchery_recipe_versions(id),CONSTRAINT fk_bo_creator FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE butchery_order_consumptions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,raw_lot_id BIGINT UNSIGNED NULL,item_id INT UNSIGNED NOT NULL,consumption_type ENUM('raw_material','additive') NOT NULL,quantity_kg DECIMAL(14,3) NOT NULL,unit_cost DECIMAL(14,4) NOT NULL,UNIQUE KEY uq_boc_source(order_id,consumption_type,item_id,raw_lot_id),CONSTRAINT fk_boc_order FOREIGN KEY(order_id) REFERENCES butchery_orders(id),CONSTRAINT fk_boc_raw FOREIGN KEY(raw_lot_id) REFERENCES butchery_raw_lots(id),CONSTRAINT fk_boc_item FOREIGN KEY(item_id) REFERENCES butchery_items(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE butchery_order_outputs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,item_id INT UNSIGNED NOT NULL,output_type ENUM('finished_product','co_product') NOT NULL,quantity_kg DECIMAL(14,3) NOT NULL,expiry_date DATE NOT NULL,unit_cost DECIMAL(14,4) NOT NULL DEFAULT 0,CONSTRAINT fk_boo_order FOREIGN KEY(order_id) REFERENCES butchery_orders(id),CONSTRAINT fk_boo_item FOREIGN KEY(item_id) REFERENCES butchery_items(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE butchery_finished_lots(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id INT UNSIGNED NOT NULL,item_id INT UNSIGNED NOT NULL,order_output_id BIGINT UNSIGNED NOT NULL,lot_number VARCHAR(100) NOT NULL UNIQUE,production_date DATE NOT NULL,expiry_date DATE NOT NULL,quantity_kg DECIMAL(14,3) NOT NULL,reserved_kg DECIMAL(14,3) NOT NULL DEFAULT 0,unit_cost DECIMAL(14,4) NOT NULL,status ENUM('available','reserved','depleted','expired','in_transit','cancelled') DEFAULT 'available',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,UNIQUE KEY uq_bfl_output(order_output_id),KEY idx_bfl_available(site_id,item_id,status,expiry_date),CONSTRAINT fk_bfl_site FOREIGN KEY(site_id) REFERENCES sites(id),CONSTRAINT fk_bfl_item FOREIGN KEY(item_id) REFERENCES butchery_items(id),CONSTRAINT fk_bfl_output FOREIGN KEY(order_output_id) REFERENCES butchery_order_outputs(id),CONSTRAINT chk_bfl_nonnegative CHECK(quantity_kg>=0 AND reserved_kg>=0 AND reserved_kg<=quantity_kg)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE butchery_finished_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,finished_lot_id BIGINT UNSIGNED NOT NULL,movement_type ENUM('production_in','sale_out','reserve','transfer_out','release','reversal') NOT NULL,quantity_kg DECIMAL(14,3) NOT NULL,stock_before_kg DECIMAL(14,3) NOT NULL,stock_after_kg DECIMAL(14,3) NOT NULL,reference_type VARCHAR(80) NOT NULL,reference_id BIGINT UNSIGNED NOT NULL,created_by INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_bfm_effect(finished_lot_id,movement_type,reference_type,reference_id),CONSTRAINT fk_bfm_lot FOREIGN KEY(finished_lot_id) REFERENCES butchery_finished_lots(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE butchery_sales(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id INT UNSIGNED NOT NULL,sale_number VARCHAR(100) NOT NULL UNIQUE,raw_lot_id BIGINT UNSIGNED NULL,finished_lot_id BIGINT UNSIGNED NULL,customer_name VARCHAR(180) NOT NULL,quantity_kg DECIMAL(14,3) NOT NULL,unit_price DECIMAL(14,4) NOT NULL,sold_at DATETIME NOT NULL,status ENUM('validated','cancelled') DEFAULT 'validated',created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_bsale_site FOREIGN KEY(site_id) REFERENCES sites(id),CONSTRAINT fk_bsale_raw FOREIGN KEY(raw_lot_id) REFERENCES butchery_raw_lots(id),CONSTRAINT fk_bsale_finished FOREIGN KEY(finished_lot_id) REFERENCES butchery_finished_lots(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE butchery_transfers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,finished_lot_id BIGINT UNSIGNED NOT NULL,source_site_id INT UNSIGNED NOT NULL,destination_site_id INT UNSIGNED NOT NULL,transfer_number VARCHAR(100) NOT NULL UNIQUE,quantity_kg DECIMAL(14,3) NOT NULL,status ENUM('draft','approved','in_transit','received','cancelled') DEFAULT 'draft',created_by INT UNSIGNED NOT NULL,approved_by INT UNSIGNED NULL,dispatched_at DATETIME NULL,received_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,UNIQUE KEY uq_bt_finished_lot(finished_lot_id),CONSTRAINT fk_bt_lot FOREIGN KEY(finished_lot_id) REFERENCES butchery_finished_lots(id),CONSTRAINT fk_bt_source FOREIGN KEY(source_site_id) REFERENCES sites(id),CONSTRAINT fk_bt_destination FOREIGN KEY(destination_site_id) REFERENCES sites(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO butchery_items(code,name,item_kind,unit,default_shelf_life_days) VALUES('MP-PORC','Carcasse de porc','raw_material','kg',5),('MP-BOEUF','Carcasse de bœuf','raw_material','kg',5),('MP-VOLAILLE','Volaille','raw_material','kg',4),('MP-POISSON','Poisson frais','raw_material','kg',3),('ADD-BOUCH','Additif boucherie','additive','kg',365),('VIANDE-DECOUPEE','Viande découpée','finished_product','kg',4),('ABATS','Abats','co_product','kg',2);
INSERT IGNORE INTO permissions(component,action,description) VALUES('butchery','read','Consulter boucherie'),('butchery','create','Créer opérations boucherie'),('butchery','validate','Valider réceptions et productions'),('butchery','update','Modifier opérations boucherie'),('butchery','delete','Annuler opérations boucherie'),('butchery','administer','Administrer boucherie');
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.component='butchery' WHERE r.slug IN('administrateur','administrateur-systeme');
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.component='butchery' AND p.action IN('read','create','update') WHERE r.slug IN('responsable-site','directeur-site','operateur-saisie','gestionnaire-stock');
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.component='butchery' AND p.action IN('read','validate') WHERE r.slug IN('direction','directeur-general','directeur-site');
DELIMITER $$
CREATE TRIGGER trg_butchery_recipe_used_update BEFORE UPDATE ON butchery_recipe_components FOR EACH ROW BEGIN IF EXISTS(SELECT 1 FROM butchery_orders WHERE recipe_version_id=OLD.recipe_version_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Recette utilisée: créez une nouvelle version'; END IF; END$$
CREATE TRIGGER trg_butchery_recipe_used_delete BEFORE DELETE ON butchery_recipe_components FOR EACH ROW BEGIN IF EXISTS(SELECT 1 FROM butchery_orders WHERE recipe_version_id=OLD.recipe_version_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Recette utilisée: créez une nouvelle version'; END IF; END$$
DELIMITER ;
